style.css:
@-moz-document domain("skool.com"), domain("www.skool.com") {
:root {
    --bg: #121417;
    --panel: #161a1f;
    --elev: #1b2027;
    --elev-2: #202632;
    --overlay: rgba(12, 14, 17, 0.72);

    --text: #e8ebf1;
    --muted: #b6bdc9;
    --subtle: #8e97a6;

    --link: #88b1ff;
    --accent: #6ea1ff;

    --border: #2a303a;
    --border-soft: #222833;

    --input-bg: #151a21;
    --input-bd: #2a3240;

    --code-bg: #11161d;
    --code-tx: #e6f1ff;

    --shadow: 0 10px 26px rgba(0, 0, 0, 0.35);
    --shadow-sm: 0 2px 10px rgba(0, 0, 0, 0.28);

    --ring: 0 0 0 2px rgba(120, 168, 255, 0.35);
    --success: #7bd88f;
    --warning: #ffcf6b;
    --danger: #ff6b6b;
  }

  /* Base */
  html, body {
    background: var(--bg) !important;
    color: var(--text) !important;
  }
  body, p, span, li, dd, dt, small, label, strong, em, b, i {
    color: var(--text);
  }
  h1, h2, h3, h4, h5, h6 {
    color: var(--text);
  }

  /* Texto secundario */
  p, .text-muted, .text-gray, .subtitle, .help, .description,
  [class*="text-gray"], [class*="text-muted"], [class*="text-secondary"] {
    color: var(--muted) !important;
  }

  /* Enlaces */
  a, a:visited {
    color: var(--link) !important;
  }
  a:hover {
    color: var(--accent) !important;
  }

  /* Paneles superiores y laterales */
  nav, [class*="navbar"], [class*="topbar"], header[role="banner"] {
    background: var(--panel) !important;
    border-bottom: 1px solid var(--border-soft) !important;
    backdrop-filter: saturate(115%) blur(6px);
  }
  aside, [class*="sidebar"], [class*="side-bar"], [class*="sidepanel"] {
    background: var(--panel) !important;
    border-right: 1px solid var(--border-soft) !important;
  }

  /* Tarjetas / posts */
  .card, [class*="card"], .box, .widget, .tile,
  .post, .thread, .topic, .comment, .reply, [class*="item-"] {
    background: var(--elev) !important;
    border: 1px solid var(--border) !important;
    box-shadow: var(--shadow);
    color: var(--text) !important;
  }
  .card header, .post header, .thread header, [class*="card-header"] {
    background: var(--elev-2) !important;
    border-bottom: 1px solid var(--border-soft) !important;
  }

  /* Cuerpos internos que quedaban claros */
  .post [class*="content"], .post [class*="body"], .post [class*="inner"],
  .card [class*="content"], .card [class*="body"], .card [class*="inner"],
  .thread [class*="content"], .thread [class*="body"],
  .topic [class*="content"], .topic [class*="body"] {
    background: var(--elev) !important;
    color: var(--text) !important;
  }

  /* Feed y contenedores */
  .feed [class*="surface"], .feed [class*="paper"], .feed [class*="sheet"],
  .feed [class*="container"], .feed [class*="panel"] {
    background: var(--elev) !important;
    color: var(--text) !important;
  }

  /* Tablas */
  table {
    background: var(--elev) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }
  thead, th {
    background: var(--elev-2) !important;
    color: var(--text) !important;
  }
  tbody tr {
    border-bottom: 1px solid var(--border-soft) !important;
  }
  tbody tr:hover {
    background: #232a36 !important;
  }

  /* Inputs, buscador y editor */
  input, textarea, select, [type="search"], [role="textbox"] {
    background: var(--input-bg) !important;
    color: var(--text) !important;
    border: 1px solid var(--input-bd) !important;
    box-shadow: none !important;
  }
  input::placeholder, textarea::placeholder {
    color: var(--subtle) !important;
  }
  input:focus, textarea:focus, select:focus {
    outline: none !important;
    box-shadow: var(--ring) !important;
    border-color: var(--accent) !important;
  }
  [placeholder*="Search"], [aria-label*="Search"],
  [placeholder*="search"], [aria-label*="search"] {
    background: var(--input-bg) !important;
    border-color: var(--input-bd) !important;
    color: var(--text) !important;
  }

  /* Editores */
  .ql-toolbar, .ql-container, .editor, .ProseMirror {
    background: var(--elev) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }

  /* Botones */
  button, .btn, [class*="btn-"], [role="button"] {
    background: #263044 !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
    box-shadow: var(--shadow-sm) !important;
  }
  button:hover, .btn:hover {
    background: #2c3850 !important;
    border-color: var(--accent) !important;
  }
  .btn-primary {
    background: #2f4f7c !important;
    border-color: #3b67a6 !important;
  }
  .btn-success { background: #224a36 !important; border-color: #2c6a4b !important; }
  .btn-warning { background: #4a3a22 !important; border-color: #6a4b2c !important; }
  .btn-danger  { background: #4a2222 !important; border-color: #6a2c2c !important; }

  /* Chips / tabs */
  .badge, [class*="badge"], .tag, [class*="pill"],
  .tab, [role="tab"], .pill {
    background: #222834 !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
  }
  .tab[aria-selected="true"], .active.tab {
    background: #2a3241 !important;
    border-color: var(--accent) !important;
  }

  /* Modales */
  .modal, [class*="modal"], .dropdown-menu,
  [class*="dropdown"], .popover, [class*="tooltip"] {
    background: var(--elev) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
    box-shadow: var(--shadow) !important;
  }
  .modal-backdrop, .overlay, [class*="backdrop"] {
    background: var(--overlay) !important;
    backdrop-filter: blur(2px);
  }

  /* Código */
  pre, code, kbd, samp {
    background: var(--code-bg) !important;
    color: var(--code-tx) !important;
    border: 1px solid #0f1624 !important;
  }
  pre code { background: transparent !important; }

  /* Estados */
  .text-success { color: var(--success) !important; }
  .text-warning { color: var(--warning) !important; }
  .text-danger  { color: var(--danger) !important; }
  .bg-success { background: rgba(123, 216, 143, 0.12) !important; }
  .bg-warning { background: rgba(255, 207, 107, 0.12) !important; }
  .bg-danger  { background: rgba(255, 107, 107, 0.12) !important; }

  /* Scrollbars */
  *::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  *::-webkit-scrollbar-track {
    background: #101317;
  }
  *::-webkit-scrollbar-thumb {
    background: #2b3444;
    border: 3px solid #101317;
    border-radius: 999px;
  }
  *::-webkit-scrollbar-thumb:hover {
    background: #35425a;
  }

  /* Colores claros forzados a gris */
  .bg-white, [class*="bg-white"], .bg-gray-50, [class*="bg-gray-50"],
  .bg-gray-100, [class*="bg-gray-100"], .bg-slate-50, [class*="bg-slate-50"],
  .bg-neutral-50, [class*="bg-neutral-50"], .bg-neutral-100, [class*="bg-neutral-100"] {
    background: var(--elev) !important;
    color: var(--text) !important;
  }

  /* Inline blancos */
  .card *[style*="background:#fff"],
  .card *[style*="background: #fff"],
  .card *[style*="rgb(255, 255, 255)"],
  .post *[style*="rgb(255, 255, 255)"],
  aside *[style*="rgb(255, 255, 255)"] {
    background: var(--elev) !important;
    color: var(--text) !important;
  }

  /* Gradientes claros */
  *[style*="linear-gradient"], [class*="gradient"] {
    background: var(--elev) !important;
    color: var(--text) !important;
  }

  /* Write something */
  [placeholder*="Write something"],
  [data-placeholder*="Write something"],
  [placeholder*="write something"],
  [data-placeholder*="write something"] {
    background: var(--input-bg) !important;
    color: var(--text) !important;
    border: 1px solid var(--input-bd) !important;
  }

  /* Widgets laterales */
  aside .card, aside [class*="card"], aside .widget, aside .box,
  aside [class*="surface"], aside [class*="panel"], aside [class*="paper"] {
    background: var(--elev) !important;
    border: 1px solid var(--border) !important;
    color: var(--text) !important;
  }
  aside .card * {
    color: inherit;
  }

  /* Bordes genéricos */
  hr, .divider, [class*="border"], .border, .divide-y > * {
    border-color: var(--border) !important;
  }

  /* Fondos blancos residuales */
  [style*="background-color: white"],
  [style*="background: white"],
  [style*="#fff"] {
    background: var(--elev) !important;
    color: var(--text) !important;
  }
}
